def _convert_parameters_to_aic_m2m_payload(class_name, param_list, conn_alias='default'):
    payload_dict = {}
    for paramdict in param_list:
        param_value = paramdict['value']
        param_name = paramdict['parameterName']
        if isinstance(param_value, list) and len(param_value) == 1:
            max_occurs = vcu_cm_base.get_complex_parameter_maxoccurs_from_nidd(class_name, param_name, conn_alias)
            if max_occurs == 1:
                payload_dict[param_name] = param_value[0]
            else:
                payload_dict[param_name] = param_value
        else:
            payload_dict[param_name] = param_value
    return json.dumps(payload_dict)


def _delta_json_file_to_aic_delta_data(delta_json_file, conn_alias='default'):
    """
    Convert the format of json from classical delta plan to
    the mo info list which is needed by aic provision delta plan(CU-OAM-ASM-LICENSED REST API)
    delta plan json file is like,
    [
      {
        "distName": "MRBTS-1/NRBTS-1",
        "operation": "update",
        "parameters": [
          {
            "parameterName": "actFdmEnhancedScheduling",
            "value": "true",
            "operation": "update"
          }
        ]
      }
    ]
    parameter format is needed by AiC provision delta plan is like,
    [{'class_name': 'NRBTS',
      'dist_name': 'MRBTS-1/NRBTS-1',
      'operation_type': 'update',
      "payload": "{\"actFdmEnhancedScheduling\": true}"}
    ]

    :param delta_json_file: filename with path to json in classical delta plan format
    :return: data structure formatted according to REST API
    """
    with open(delta_json_file) as admin_json:
        admin_json_struct = json.load(admin_json)
        aic_m2m = []
        for distname_dict in admin_json_struct:
            aic_distname_dict = {}
            class_name = distname_dict['distName'].split('/')[-1].split('-')[0]
            aic_distname_dict['operation_type'] = distname_dict['operation']
            aic_distname_dict['dist_name'] = distname_dict['distName']
            aic_distname_dict['class_name'] = class_name
            aic_distname_dict['payload'] = _convert_parameters_to_aic_m2m_payload(class_name,
                                                                                  distname_dict['parameters'],
                                                                                  conn_alias=conn_alias)
            aic_m2m.append(aic_distname_dict)
    return aic_m2m


def switching_actcli_by_delta_commissioning(actcli_value, conn_alias='default', timeout=30):
    """
    Changing the value of actCli parameter by the given value.

    :param str/boolean actcli_value: true or false
    :param str conn_alias: rest api connection alias, default value is 'default'.
    :param Union[int,str] timeout: (optional) Timeout for the delta commission finished, default is 30s.
    """
    # pass
    str_actcli_value = str(actcli_value).lower()
    mrbts = vcu_ope_base.get_cu_mrbts_id_from_webem(use_m2m=False, conn_alias=conn_alias)
    mo = '{}/MNL-1/MNLENT-1/FEATCADM-1'.format(mrbts)
    curr_actcli = vcu_cm_base.get_parameter_value_from_current_plan(mo_dn=mo, parameter_path='actCli',
                                                                    conn_alias=conn_alias)
    if curr_actcli != str_actcli_value:
        logger.info('{} Changing actCli under {} to {} {}'.format(LOG_HEAD, mo, actcli_value, LOG_END))
        changed_value = [[mo, {'actCli': str_actcli_value}, 'update']]
        fast_delta_commissioning_by_delta_data(delta_data_list=changed_value,
                                               use_m2m=False,
                                               conn_alias=conn_alias,
                                               timeout=timeout)
    else:
        logger.info('{} The value of actCli under {} is {}, no need to change {}'.format(LOG_HEAD, mo,
                                                                                         actcli_value, LOG_END))


def fast_delta_commissioning_by_delta_json_file(json_file_path, use_m2m=True, conn_alias='default', timeout=300):
    """
    delta commission using a delta plan file which is classical bts delta json format, e.g,

        [

            {

                "distName": "MRBTS-1/NRBTS-1/NRCELL-1",

                "operation": "update",

                "parameters": [

                    {

                        "parameterName": "actBeamforming",

                        "value": "true",

                        "operation": "update"

                    },

                    {

                        "parameterName": "actPerCsiReportBundlingTddFr1",

                        "value": "true",

                        "operation": "update"

                    },

                    {

                        "parameterName": "beamSet",

                        "value": [

                            {

                                "basicBeamSet": "beamSet_6",

                                "leftEdgeAngle": "60",

                                "nrBtsBeamRefinementP2": "false",

                               "rightEdgeAngle": "60"

                            }

                        ],

                        "operation": "update"

                    }

            }

        ]

    :param str json_file_path: the delta json file path.
    :param boolean use_m2m: Whether use the M2M API interface, default is True.
                            If actCli is disabled, it should be set to False.
    :param str conn_alias: rest api connection alias, default value is 'default'.
    :param Union[int,str] timeout: (optional) Timeout for the delta commission finished, default is 300s.
    """
    aic_delta_data = _delta_json_file_to_aic_delta_data(delta_json_file=json_file_path, conn_alias=conn_alias)
    logger.info('{} delta data are as below\n{}\n'.format(LOG_HEAD, aic_delta_data))
    logger.info('\n{} Starting to do delta commissioning {}'.format(LOG_HEAD, LOG_END))
    vcu_cm_base.fast_delta_commissioning(delta_data=aic_delta_data, use_m2m=use_m2m,
                                         conn_alias=conn_alias, timeout_4_provision_finished=timeout)


def fast_delta_commissioning_by_delta_data(delta_data_list, use_m2m=True, conn_alias='default', timeout=300):
    """
    This keyword is used to fast activate delta plan, actually, the provision delta plan REST API is called.
    No need to generate, validate and activate delta plan file.

    :param list delta_data_list: Parameters lists that need to be modified.
                                 Each element is constructed with MO, a dict of parameter value pair and operation type for *MO*.
                                 operation type can only be 'create', 'delete', and 'update'. e.g,
                                 [['mo1', {'param1/0/sub_param_1':'value1_1',
                                           'param1/0/sub_param_2':'value1_2',
                                           'param2':'value2'}, 'replace'],
                                  ['mo2', {'param1':'value1', 'param2':'value2'}, 'create']]
    :param boolean use_m2m: Whether use M2M API, if the actCli is disabled, it should be set to False, default is True.
    :param str conn_alias: rest api connection alias, default value is 'default'.
    :param Union[int,str] timeout: (optional) Timeout for the delta plan provision finished, default is 300s.
    :return list: The original values of the parameters that need to be modified.
                  It can be used to restore the parameters in case teardown.
                  The data structure is the same as the argument - delta_data_list.
    """
    # org_delta_data_list = get_parameters_value_for_multi_mo(delta_data_list, conn_alias)
    aic_delta_data = generic_utils.delta_params_data_to_provision_delta_plan_req_body(delta_data_list=delta_data_list)
    logger.info('{} delta data are as below\n{}\n'.format(LOG_HEAD, aic_delta_data))
    logger.info('\n{} Starting to do delta commissioning {}'.format(LOG_HEAD, LOG_END))
    vcu_cm_base.fast_delta_commissioning(delta_data=aic_delta_data,
                                         use_m2m=use_m2m,
                                         conn_alias=conn_alias,
                                         timeout_4_provision_finished=timeout)
    # return org_delta_data_list


def delta_commissioning_step_by_step(delta_data_list, delta_plan_name='DELTA-PLAN-1',
                                     force_reset=True, auto_lock_cells=True, conn_alias='default',
                                     timeout=300):
    """
    This keyword is used to do delta commissioning step by step by given a delta data list for CU.
    This keyword includes the functions of generating delta plan file, updating parameters, validating and activating delta plan.

    :param list delta_data_list: Parameters lists that need to be modified.
                                 Each element is constructed with MO, a dict of parameter value pair and operation type for *parameters*.
                                 Operation type can only be 'add', 'replace', 'remove' and 'revert'. e.g,
                                 [
                                      ['mo1', {'param1/0/sub_param_1':'value1_1',
                                              'param1/0/sub_param_2':'value1_2',
                                              'param2':'value2'}, 'replace'],
                                      ['mo2', {'param1':'', 'param1/0/sub_param1':'value1',
                                               'param2/1/sub_param1':'value2',
                                               'param2/1/sub_param2':'value3',
                                               'param2/2/sub_param1':'value4',
                                               'param3': 'value3'}, 'add'],
                                      ['mo2', {'param1':'value1', 'param2':'value2'}, 'replace']
                                      ['mo3', {'param1':'', 'param2/0':'', 'param2/1/sub_param1':'value',
                                               'param3': 'value3'}, 'remove']
                                 ]
    :param str delta_plan_name: delta plan name, default value is DELTA-PLAN-1.
    :param bool force_reset: The force reset option (default: true)
    :param bool auto_lock_cells: The auto lock cells option (default: true)
    :param str conn_alias: rest api connection alias, default value is 'default'.
    :param Union[int,str] timeout: (optional) Timeout for the delta plan provision finished, default is 30.
    :return list: The original values of the parameters that need to be modified.
                  It can be used to restore the parameters in case teardown.
                  The data structure is the same as the argument `delta_data_list`.
    """
    # logger.info('\nGathering original values of the parameters:\n')
    # org_delta_data_list = _get_parameters_value_for_multi_mo(delta_data_list, conn_alias)
    logger.info('\nGenerating translated delta file:\n')
    delta_file = []
    mo_list = []
    for updated_item in delta_data_list:
        mo_dist_name = updated_item[0]
        operation_type = updated_item[2]
        if operation_type == 'replace':
            operation_type = 'update'
        if operation_type == 'add':
            operation_type = 'create'
        if operation_type == 'remove':
            operation_type = 'delete'
        param_delta_dict = updated_item[1]
        delta_file_item = {}
        delta_file_item['distName'] = mo_dist_name
        delta_file_item['operation'] = 'update'
        item_parameter_list = []
        for param_name, param_value in param_delta_dict.items():
            param_item = {}
            param_item['parameterName'] = param_name
            param_item['value'] = param_value
            param_item['operation'] = operation_type
            item_parameter_list.append(param_item)
        delta_file_item['parameters'] = item_parameter_list
        if mo_dist_name not in mo_list:
            mo_list.append(mo_dist_name)
            delta_file.append(delta_file_item)
        else:
            index = mo_list.index(mo_dist_name)
            delta_file[index]['parameters'].extend(item_parameter_list)

    delta_file_json = json.dumps(delta_file)
    logger.info('\nNew delta file:\n {}'.format(delta_file_json))
    logger.info('\nPerforming delta recommissioning:\n')
    return vcu_cm_base._perform_delta_recommissioning(delta_file=delta_file_json, timeout=timeout,
                                                      connection=conn_alias)

    # return org_delta_data_list


def _get_parameters_value_for_multi_mo(param_data_list, conn_alias='default'):
    """
    Get the values of parameters under multiple MOs at one time from current scf.

    :param param_data_list: parameters lists that need to be fetched values.
                            The data structure is the same as `delta_data_list` in keyword `delta_commissioning_step_by_step`.
                            e.g,
                            [
                              ['mo1', {'param1/0/sub_param_1':'value1_1',
                                      'param1/0/sub_param_2':'value1_2',
                                      'param2':'value2'}, 'replace'],
                              ['mo2', {'param1':'', 'param1/0/sub_param1':'value1',
                                       'param2/1/sub_param1':'value2',
                                       'param2/1/sub_param2':'value3',
                                       'param2/2/sub_param1':'value4',
                                       'param3': 'value3'}, 'add'],
                              ['mo3', {'param1':'', 'param2/0':''}, 'remove']
                            ]
    :param str conn_alias: rest api connection alias, default value is 'default'.
    :return list: The values of the given parameters, the data structure is the same as argument `param_data_list`
    """
    all_delta_data_list = []
    for delta_data in param_data_list:
        org_param_value_dict = {}
        mo_dn = delta_data[0]
        operation_type = delta_data[2]
        if operation_type == 'replace':
            for param_name, param_value in delta_data[1].copy().items():
                org_param_value = vcu_cm_base.get_parameter_value_from_current_plan(mo_dn=mo_dn,
                                                                                    parameter_path=param_name,
                                                                                    conn_alias=conn_alias)
                if org_param_value != param_value:
                    org_param_value_dict[param_name] = org_param_value
                else:
                    delta_data[1].pop(param_name)

        if org_param_value_dict:
            all_delta_data_list.append([mo_dn, org_param_value_dict, operation_type])
    return all_delta_data_list


def _delta_xml_file_to_aic_provision_delta_plan_payload(xml_file_path, conn_alias='default'):
    # Define the XML namespaces used in the document
    namespaces = {'r': 'raml21.xsd'}

    # Load the XML file
    tree = ET.parse(xml_file_path)
    root = tree.getroot()

    # Find all <managedObject> elements
    results = []
    for obj in root.findall('.//r:managedObject', namespaces):
        class_name = obj.attrib['class'].split(':')[1]
        dist_name = obj.attrib['distName']
        operation_type = obj.attrib['operation']
        payload = {}
        for param in obj.findall('r:p', namespaces):
            payload[param.attrib['name']] = param.text
        for lst in obj.findall('r:list', namespaces):
            if lst.findall('r:item', namespaces):
                max_occurs = vcu_cm_base.get_complex_parameter_maxoccurs_from_nidd(class_name,
                                                                                   lst.attrib['name'],
                                                                                   conn_alias=conn_alias)
                if max_occurs > 1:
                    items = []
                    for item in lst.findall('r:item', namespaces):
                        item_payload = {}
                        for param in item.findall('r:p', namespaces):
                            item_payload[param.attrib['name']] = param.text
                        items.append(item_payload)
                    payload[lst.attrib['name']] = items
                else:
                    item = lst.findall('r:item', namespaces)[0]
                    item_payload = {}
                    for param in item.findall('r:p', namespaces):
                        item_payload[param.attrib['name']] = param.text
                    payload[lst.attrib['name']] = item_payload
            else:
                payload[lst.attrib['name']] = [p.text for p in lst.findall('r:p', namespaces)]
        results.append({
            'class_name': class_name,
            'dist_name': dist_name,
            'operation_type': operation_type,
            'payload': json.dumps(payload)
        })

    return results


def fast_delta_commission_with_delta_xml_file(xml_file_path, use_m2m=True, conn_alias='default', timeout=300):
    """
    delta commissioning by given a delta xml plan file.

    :param str xml_file_path: The delta xml file path.
    :param boolean use_m2m: Whether use the M2M API interface, default is True.
                            If actCli is disabled, it should be set to False.
    :param str conn_alias: rest api connection alias, default value is 'default'.
    :param Union[int,str] timeout: (optional) Timeout for the delta plan provision finished, default is 300s.
    """
    aic_delta_data = _delta_xml_file_to_aic_provision_delta_plan_payload(xml_file_path=xml_file_path,
                                                                         conn_alias=conn_alias)
    logger.info('{} delta data are as below\n{}\n'.format(LOG_HEAD, aic_delta_data))
    logger.info('\n{} Starting to do delta commissioning {}'.format(LOG_HEAD, LOG_END))
    vcu_cm_base.fast_delta_commissioning(delta_data=aic_delta_data, use_m2m=use_m2m, conn_alias=conn_alias,
                                         timeout_4_provision_finished=timeout)
